import os
import re

ROOT = "/Users/kristinarash/DEV"
repos = [l.strip() for l in open("/Users/kristinarash/.claude/jobs/c9825473/tmp/repos.txt") if l.strip()]
pat = re.compile(r"deliverables|DELIV|OUT_DIR|output_dir|OUTPUT_DIR|outputs/|--out\b|default=.*(out|output|deliver)", re.I)
exts = (".py", ".R", ".ps1", ".sh", ".js", ".ts", ".mjs")
skip = ("/.git/", "node_modules", "/.venv/", "/venv/", "/__pycache__/")

for rel in repos:
    base = os.path.join(ROOT, rel)
    if not os.path.isdir(base):
        print("MISSING", rel)
        continue
    hits = []
    for dp, dn, fn in os.walk(base):
        dn[:] = [d for d in dn if d not in (".git", "node_modules", ".venv", "venv", "__pycache__")]
        if dp.count(os.sep) - base.count(os.sep) > 3:
            dn[:] = []
            continue
        for f in fn:
            if not f.endswith(exts):
                continue
            p = os.path.join(dp, f)
            try:
                for i, line in enumerate(open(p, encoding="utf-8", errors="ignore"), 1):
                    if pat.search(line):
                        hits.append(f"{os.path.relpath(p, base)}:{i}")
                        break
            except OSError:
                pass
    print(f"{rel} :: {len(hits)} file(s) :: {', '.join(hits[:6]) if hits else 'none'}")

